#include <limits.h>
#include <stdbool.h>
#include <stdio.h>

static bool checked_add_int(int a, int b, int *out) {
    if (out == NULL) {
        return false;
    }
    if ((b > 0 && a > INT_MAX - b) ||
        (b < 0 && a < INT_MIN - b)) {
        return false;
    }
    *out = a + b;
    return true;
}

int main(void) {
    int result = 99;

    if (checked_add_int(20, 22, &result)) {
        printf("20 + 22 = %d\n", result);
    }
    result = 99;
    if (!checked_add_int(INT_MAX, 1, &result)) {
        printf("overflow rejected; result remains %d\n", result);
    }
    result = 99;
    if (!checked_add_int(INT_MIN, -1, &result)) {
        printf("underflow rejected; result remains %d\n", result);
    }
    return 0;
}

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

static int *allocate_ints(size_t count) {
    int *items;

    if (count == 0 || count > SIZE_MAX / sizeof *items) {
        return NULL;
    }
    items = malloc(count * sizeof *items);
    return items;
}

int main(void) {
    const size_t count = 4;
    int *values = allocate_ints(count);

    if (values == NULL) {
        puts("allocation rejected or unavailable");
        return 1;
    }
    for (size_t i = 0; i < count; ++i) {
        values[i] = (int)(i + 1u);
    }
    printf("allocated %zu integers; last=%d\n", count, values[count - 1u]);
    free(values);
    return 0;
}
